              whiteSpace: "nowrap",
            }}
          >
            {heroText}
          </div>
          <div
            style={{
              marginTop: 16 * u,
              fontFamily,
              fontWeight: 400,
              fontSize: 24 * u,
              letterSpacing: "-0.01em",
              color: p.muted,
              opacity: cap,
              transform: `translateY(${(1 - cap) * 8 * u}px)`,
              whiteSpace: "nowrap",
            }}
          >
            {caption}
          </div>
        </div>
      </ScaleLayer>

      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 85% 85% at 50% 50%, transparent 64%, ${bg} 100%)`,
          opacity: 0.5,
        }}
      />
      {grain ? <Grain opacity={p.grain} /> : null}
    </AbsoluteFill>
  );
}

